CREATE FUNCTION public.add_session_exercise(p_session_id bigint, p_exercise_id bigint, p_gym_equipment_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  session_owner_id uuid := (select auth.uid());
  session_record public.workout_sessions;
  resolved_equipment_id bigint := null;
  equip_name_snapshot text := null;
  next_order integer;
  new_exercise_record public.session_exercises;
  new_set_record public.exercise_sets;
begin
  if session_owner_id is null then
    raise exception using errcode = '42501', message = 'Authentication is required.';
  end if;

  -- Lock the session row to prevent race conditions during concurrent additions
  select * into session_record
  from public.workout_sessions
  where id = p_session_id and owner_id = session_owner_id and status = 'in_progress'
  for update;

  if not found then
    raise exception using errcode = '42501', message = 'Active session not found or not owned by current user.';
  end if;

  if not exists (
    select 1 from public.exercises where id = p_exercise_id
  ) then
    raise exception using errcode = '22023', message = 'Exercise not found in catalogue.';
  end if;

  if p_gym_equipment_id is not null then
    select name into equip_name_snapshot
    from public.gym_equipment
    where id = p_gym_equipment_id
      and owner_id = session_owner_id
      and gym_id = session_record.gym_id;

    if not found then
      raise exception using errcode = '42501', message = 'Equipment not found, inactive, or not compatible with session gym.';
    end if;
    resolved_equipment_id := p_gym_equipment_id;
  else
    -- Resolve default equipment and snapshot deterministically from prior completed workouts
    select se_hist.gym_equipment_id, ge.name
    into resolved_equipment_id, equip_name_snapshot
    from public.session_exercises se_hist
    join public.workout_sessions ws_hist
      on ws_hist.id = se_hist.session_id and ws_hist.owner_id = se_hist.owner_id
    left join public.gym_equipment ge
      on ge.id = se_hist.gym_equipment_id and ge.owner_id = session_owner_id
    where ws_hist.owner_id = session_owner_id
      and ws_hist.gym_id = session_record.gym_id
      and ws_hist.status = 'completed'
      and se_hist.exercise_id = p_exercise_id
      and se_hist.gym_equipment_id is not null
    order by
      ws_hist.performed_on desc,
      ws_hist.created_at desc,
      ws_hist.id desc,
      se_hist.exercise_order desc,
      se_hist.id desc
    limit 1;
  end if;

  select coalesce(max(exercise_order), 0) + 1 into next_order
  from public.session_exercises
  where session_id = p_session_id and owner_id = session_owner_id;

    owner_id,
    session_id,
    exercise_order,
    exercise_id,
    gym_equipment_id,
    equipment_name_snapshot
  )
  values (
    session_owner_id,
    p_session_id,
    next_order,
    p_exercise_id,
    resolved_equipment_id,
    equip_name_snapshot
  )
  returning * into new_exercise_record;

    owner_id,
    session_exercise_id,
    set_number,
    weight,
    reps,
    is_warmup,
    reported_rir_bucket,
    rir_source
  )
  values (
    session_owner_id,
    new_exercise_record.id,
    1,
    null,
    null,
    false,
    null,
    null
  )
  returning * into new_set_record;

  return jsonb_build_object(
    'id', new_exercise_record.id,
    'session_id', new_exercise_record.session_id,
    'exercise_order', new_exercise_record.exercise_order,
    'exercise_id', new_exercise_record.exercise_id,
    'gym_equipment_id', new_exercise_record.gym_equipment_id,
    'equipment_name_snapshot', new_exercise_record.equipment_name_snapshot,
    'initial_set_id', new_set_record.id
  );
end;
$$;


--
-- Name: body_weight_daily_series(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.body_weight_daily_series() RETURNS TABLE(measured_on date, weight_kg numeric, provenance text, previous_measured_on date, previous_weight_kg numeric, next_measured_on date, next_weight_kg numeric)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with owned as (
    select measurement.measured_on, measurement.weight_kg
    from public.body_weight_measurements measurement
    where measurement.owner_id = (select auth.uid())
  ), bounds as (
    select min(measured_on) first_day, max(measured_on) last_day from owned
  ), days as (
    select generate_series(first_day, last_day, interval '1 day')::date measured_on from bounds
  ), neighbours as (
    select days.measured_on,
      previous.measured_on previous_measured_on, previous.weight_kg previous_weight_kg,
      following.measured_on next_measured_on, following.weight_kg next_weight_kg
    from days
    left join lateral (select * from owned where owned.measured_on <= days.measured_on order by owned.measured_on desc limit 1) previous on true
    left join lateral (select * from owned where owned.measured_on >= days.measured_on order by owned.measured_on asc limit 1) following on true
  )
  select neighbours.measured_on,
    case when previous_measured_on = next_measured_on then previous_weight_kg
      else previous_weight_kg + (next_weight_kg - previous_weight_kg)
        * ((neighbours.measured_on - previous_measured_on)::numeric / nullif(next_measured_on - previous_measured_on, 0)) end,
    case when previous_measured_on = next_measured_on then 'measured' else 'interpolated' end,
    previous_measured_on, previous_weight_kg, next_measured_on, next_weight_kg
  from neighbours
  where previous_measured_on is not null and next_measured_on is not null
  order by neighbours.measured_on;
$$;


