--
-- Name: remove_exercise_set(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_exercise_set(p_set_id bigint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  session_owner_id uuid := (select auth.uid());
  target_session_exercise_id bigint;
  target_session_id bigint;
begin
  if session_owner_id is null then
    raise exception using errcode = '42501', message = 'Authentication is required.';
  end if;

  -- Verify active session ownership and lock session row
  select se.id, ws.id
  into target_session_exercise_id, target_session_id
  from public.exercise_sets es
  join public.session_exercises se
    on se.id = es.session_exercise_id and se.owner_id = es.owner_id
  join public.workout_sessions ws
    on ws.id = se.session_id and ws.owner_id = se.owner_id
  where es.id = p_set_id
    and es.owner_id = session_owner_id
    and ws.status = 'in_progress'
  for update of ws;

  if not found then
    raise exception using errcode = '42501', message = 'Set not found, not active, or not owned by current user.';
  end if;

  delete from public.exercise_sets
  where id = p_set_id and owner_id = session_owner_id;

  with ordered as (
    select id, row_number() over (order by set_number, id)::smallint as new_set_number
    from public.exercise_sets
    where session_exercise_id = target_session_exercise_id and owner_id = session_owner_id
  )
  update public.exercise_sets es
  set set_number = ordered.new_set_number
  from ordered
  where es.id = ordered.id and es.set_number <> ordered.new_set_number;

  return true;
end;
$$;


--
-- Name: remove_session_exercise(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_session_exercise(p_session_exercise_id bigint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  session_owner_id uuid := (select auth.uid());
  target_session_id bigint;
begin
  if session_owner_id is null then
    raise exception using errcode = '42501', message = 'Authentication is required.';
  end if;

  -- Verify active session ownership and lock session row
  select ws.id into target_session_id
  from public.session_exercises se
  join public.workout_sessions ws
    on ws.id = se.session_id and ws.owner_id = se.owner_id
  where se.id = p_session_exercise_id
    and se.owner_id = session_owner_id
    and ws.status = 'in_progress'
  for update of ws;

  if not found then
    raise exception using errcode = '42501', message = 'Session exercise not found, not active, or not owned by current user.';
  end if;

  delete from public.session_exercises
  where id = p_session_exercise_id and owner_id = session_owner_id;

  with ordered as (
    select id, row_number() over (order by exercise_order, id)::integer as new_order
    from public.session_exercises
    where session_id = target_session_id and owner_id = session_owner_id
  )
  update public.session_exercises se
  set exercise_order = ordered.new_order
  from ordered
  where se.id = ordered.id and se.exercise_order <> ordered.new_order;

  return true;
end;
$$;


--
-- Name: reorder_session_exercises(bigint, bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_session_exercises(p_session_id bigint, p_exercise_ids bigint[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  session_owner_id uuid := (select auth.uid());
  current_exercise_ids bigint[];
  order_offset integer;
begin
  if session_owner_id is null then
    raise exception using errcode = '42501', message = 'Authentication is required.';
  end if;

  if not exists (
    select 1 from public.workout_sessions
    where id = p_session_id and owner_id = session_owner_id and status = 'in_progress'
  ) then
    raise exception using errcode = '42501', message = 'Session not found, not active, or not owned by current user.';
  end if;

  select array_agg(id order by id) into current_exercise_ids
  from public.session_exercises
  where session_id = p_session_id and owner_id = session_owner_id;

  if coalesce(cardinality(p_exercise_ids), 0) <> coalesce(cardinality(current_exercise_ids), 0)
     or exists (
       select 1 from unnest(p_exercise_ids) as passed(id)
       group by id having count(*) > 1
     )
     or exists (
       select 1 from unnest(p_exercise_ids) as passed(id)
       where passed.id is null or not (passed.id = any(current_exercise_ids))
     ) then
    raise exception using errcode = '22023', message = 'Submitted exercise IDs do not match the current session exercises.';
  end if;

  select coalesce(max(exercise_order), 0) + cardinality(p_exercise_ids)
    into order_offset
  from public.session_exercises
  where session_id = p_session_id and owner_id = session_owner_id;

  update public.session_exercises se
  set exercise_order = order_offset + pos.new_order
  from (
    select id, ordinality::integer as new_order
    from unnest(p_exercise_ids) with ordinality as ord(id, ordinality)
  ) pos
  where se.id = pos.id and se.session_id = p_session_id and se.owner_id = session_owner_id;

  update public.session_exercises se
  set exercise_order = pos.new_order
  from (
    select id, ordinality::integer as new_order
    from unnest(p_exercise_ids) with ordinality as ord(id, ordinality)
  ) pos
  where se.id = pos.id and se.session_id = p_session_id and se.owner_id = session_owner_id;
end;
$$;


