CREATE FUNCTION public.save_workout_preset(p_preset_id bigint, p_name text, p_exercise_ids bigint[]) RETURNS public.workout_presets
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  preset_owner_id uuid := (select auth.uid());
  normalized_name text := regexp_replace(btrim(p_name), '\s+', ' ', 'g');
  saved_preset public.workout_presets;
begin
