-- Name: set_workout_preset_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_workout_preset_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: start_or_resume_workout_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_or_resume_workout_session() RETURNS public.workout_sessions
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  select public.start_or_resume_workout_session(null::bigint);
$$;


--
-- Name: FUNCTION start_or_resume_workout_session(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.start_or_resume_workout_session() IS 'Atomically returns the authenticated owner''s active session or creates one blank in-progress session.';


--
-- Name: start_or_resume_workout_session(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_or_resume_workout_session(p_preset_id bigint) RETURNS public.workout_sessions
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  session_owner_id uuid := (select auth.uid());
  active_session public.workout_sessions;
  created_session boolean;
begin
  if session_owner_id is null then
    raise exception using errcode = '42501', message = 'Authentication is required.';
  end if;
  if p_preset_id is not null and not exists (
    select 1 from public.workout_presets where id = p_preset_id and owner_id = session_owner_id
  ) then
    raise exception using errcode = '42501', message = 'Preset not found or not owned by the current user.';
  end if;
  if p_preset_id is not null and not exists (
    select 1 from public.workout_preset_exercises where preset_id = p_preset_id and owner_id = session_owner_id
  ) then
    raise exception using errcode = '22023', message = 'The selected preset has no exercises.';
  end if;

  values (session_owner_id, null, current_date, 'in_progress')
  on conflict (owner_id) where status = 'in_progress' do nothing
  returning * into active_session;
  created_session := found;
  if not created_session then
    select * into active_session from public.workout_sessions
    where owner_id = session_owner_id and status = 'in_progress';
    return active_session;
  end if;

  if p_preset_id is not null then
    with randomized_exercises as (
      select membership.exercise_id, row_number() over (order by random())::integer as exercise_order
      from public.workout_preset_exercises as membership
      where membership.preset_id = p_preset_id and membership.owner_id = session_owner_id
    ), inserted_exercises as (
      select session_owner_id, active_session.id, randomized.exercise_order, exercise.id
      from randomized_exercises as randomized
      join public.exercises as exercise on exercise.id = randomized.exercise_id
      returning id, exercise_id
    )
      owner_id, session_exercise_id, set_number, reported_rir_bucket, rir_source
    )
    select session_owner_id, inserted.id, generated.set_number::smallint, 0, 'historical_backfill'
    from inserted_exercises as inserted
    join public.workout_preset_exercises as membership
      on membership.preset_id = p_preset_id
     and membership.owner_id = session_owner_id
     and membership.exercise_id = inserted.exercise_id
    cross join lateral generate_series(1, membership.set_count) as generated(set_number);
  end if;
  return active_session;
end;
$$;


--
-- Name: FUNCTION start_or_resume_workout_session(p_preset_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.start_or_resume_workout_session(p_preset_id bigint) IS 'Creates an owner-scoped session. Blank preset slots carry historical placeholder provenance until explicit user RIR is saved.';


--
-- Name: start_or_resume_workout_session(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_or_resume_workout_session(p_gym_id bigint DEFAULT NULL::bigint, p_preset_id bigint DEFAULT NULL::bigint) RETURNS public.workout_sessions
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  session_owner_id uuid := (select auth.uid());
  active_session public.workout_sessions;
  preset_name_snapshot text;
  created_session boolean;
begin
  if session_owner_id is null then
    raise exception using errcode = '42501', message = 'Authentication is required.';
  end if;

  select * into active_session
  from public.workout_sessions
  where owner_id = session_owner_id and status = 'in_progress'
  limit 1;

  if found then
    return active_session;
  end if;

  if p_gym_id is null then
    raise exception using errcode = '22023', message = 'A gym is required to start a new workout session.';
  end if;

  if not exists (
    select 1 from public.gyms where id = p_gym_id and owner_id = session_owner_id
  ) then
    raise exception using errcode = '42501', message = 'Gym not found or not owned by the current user.';
  end if;

  if p_preset_id is not null then
    select name into preset_name_snapshot
    from public.workout_presets
    where id = p_preset_id and owner_id = session_owner_id;

    if not found then
      raise exception using errcode = '42501', message = 'Preset not found or not owned by the current user.';
    end if;

    if not exists (
      select 1 from public.workout_preset_exercises
      where preset_id = p_preset_id and owner_id = session_owner_id
    ) then
      raise exception using errcode = '22023', message = 'The selected preset has no exercises.';
    end if;
  end if;

    owner_id, gym_id, performed_on, status, source_preset_id, source_preset_name
  )
  values (
    session_owner_id, p_gym_id, current_date, 'in_progress', p_preset_id, preset_name_snapshot
  )
  on conflict (owner_id) where status = 'in_progress' do nothing
  returning * into active_session;
  created_session := found;

  if not created_session then
    select * into active_session
    from public.workout_sessions
    where owner_id = session_owner_id and status = 'in_progress';
    return active_session;
  end if;

  if p_preset_id is not null then
    with randomized_exercises as (
      select
        membership.exercise_id,
        row_number() over (order by random())::integer as exercise_order
      from public.workout_preset_exercises as membership
      where membership.preset_id = p_preset_id
        and membership.owner_id = session_owner_id
    ), resolved_equipment as (
      select
        re.exercise_id,
        re.exercise_order,
        (
          select se_hist.gym_equipment_id
          from public.session_exercises se_hist
          join public.workout_sessions ws_hist
            on ws_hist.id = se_hist.session_id and ws_hist.owner_id = se_hist.owner_id
          where ws_hist.owner_id = session_owner_id
            and ws_hist.gym_id = p_gym_id
            and ws_hist.status = 'completed'
            and se_hist.exercise_id = re.exercise_id
            and se_hist.gym_equipment_id is not null
          order by
            ws_hist.performed_on desc,
            ws_hist.created_at desc,
            ws_hist.id desc,
            se_hist.exercise_order desc,
            se_hist.id desc
          limit 1
        ) as default_gym_equipment_id
      from randomized_exercises re
    ), inserted_exercises as (
        owner_id, session_id, exercise_order, exercise_id, gym_equipment_id, equipment_name_snapshot
      )
      select
        session_owner_id,
        active_session.id,
        resolved.exercise_order,
        resolved.exercise_id,
        resolved.default_gym_equipment_id,
        ge.name
      from resolved_equipment as resolved
      left join public.gym_equipment ge
        on ge.id = resolved.default_gym_equipment_id
       and ge.owner_id = session_owner_id
      returning id, exercise_id
    )
      owner_id, session_exercise_id, set_number, weight, reps, is_warmup, reported_rir_bucket, rir_source
    )
    select
      session_owner_id,
      inserted.id,
      generated.set_number::smallint,
      null,
      null,
      false,
      null,
      null
    from inserted_exercises as inserted
    join public.workout_preset_exercises as membership
      on membership.preset_id = p_preset_id
     and membership.owner_id = session_owner_id
     and membership.exercise_id = inserted.exercise_id
    cross join lateral generate_series(1, membership.set_count) as generated(set_number);
  end if;

  return active_session;
end;
$$;


