--
-- Name: exercise_sets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.exercise_sets (
    id bigint NOT NULL,
    owner_id uuid NOT NULL,
    session_exercise_id bigint NOT NULL,
    set_number smallint NOT NULL,
    weight numeric,
    reps integer,
    rpe numeric(3,1),
    is_warmup boolean DEFAULT false NOT NULL,
    is_drop_set boolean DEFAULT false NOT NULL,
    is_superset boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    estimated_1rm_brzycki numeric GENERATED ALWAYS AS (
CASE
    WHEN ((weight IS NOT NULL) AND ((reps >= 1) AND (reps <= 36))) THEN round(((weight * (36)::numeric) / ((37 - reps))::numeric), 2)
    ELSE NULL::numeric
END) STORED,
    estimated_1rm_epley numeric GENERATED ALWAYS AS (
CASE
    WHEN ((weight IS NOT NULL) AND (reps > 0)) THEN round((weight * ((1)::numeric + ((reps)::numeric / 30.0))), 2)
    ELSE NULL::numeric
END) STORED,
    estimated_1rm_low numeric GENERATED ALWAYS AS (
CASE
    WHEN ((weight IS NOT NULL) AND ((reps >= 1) AND (reps <= 36))) THEN round(LEAST(((weight * (36)::numeric) / ((37 - reps))::numeric), (weight * ((1)::numeric + ((reps)::numeric / 30.0)))), 2)
    ELSE NULL::numeric
END) STORED,
    estimated_1rm_high numeric GENERATED ALWAYS AS (
CASE
    WHEN ((weight IS NOT NULL) AND ((reps >= 1) AND (reps <= 36))) THEN round(GREATEST(((weight * (36)::numeric) / ((37 - reps))::numeric), (weight * ((1)::numeric + ((reps)::numeric / 30.0)))), 2)
    ELSE NULL::numeric
END) STORED,
    reported_rir_bucket smallint,
    rir_source text,
    estimated_1rm_brzycki_rir_adjusted numeric GENERATED ALWAYS AS (
CASE
    WHEN ((NOT is_warmup) AND ((reported_rir_bucket >= 0) AND (reported_rir_bucket <= 3)) AND (weight IS NOT NULL) AND (((reps + reported_rir_bucket) >= 1) AND ((reps + reported_rir_bucket) <= 36))) THEN round(((weight * (36)::numeric) / ((37 - (reps + reported_rir_bucket)))::numeric), 2)
    ELSE NULL::numeric
END) STORED,
    estimated_1rm_epley_rir_adjusted numeric GENERATED ALWAYS AS (
CASE
    WHEN ((NOT is_warmup) AND ((reported_rir_bucket >= 0) AND (reported_rir_bucket <= 3)) AND (weight IS NOT NULL) AND ((reps + reported_rir_bucket) > 0)) THEN round((weight * ((1)::numeric + (((reps + reported_rir_bucket))::numeric / 30.0))), 2)
    ELSE NULL::numeric
END) STORED,
    CONSTRAINT exercise_sets_reported_rir_bucket_check CHECK (((reported_rir_bucket IS NULL) OR ((reported_rir_bucket >= 0) AND (reported_rir_bucket <= 4)))),
    CONSTRAINT exercise_sets_reps_check CHECK ((reps >= 0)),
    CONSTRAINT exercise_sets_rir_provenance_check CHECK (((reported_rir_bucket IS NULL) = (rir_source IS NULL))),
    CONSTRAINT exercise_sets_rir_source_check CHECK (((rir_source IS NULL) OR (rir_source = ANY (ARRAY['user_entered'::text, 'historical_backfill'::text])))),
    CONSTRAINT exercise_sets_rpe_check CHECK (((rpe >= (1)::numeric) AND (rpe <= (10)::numeric))),
    CONSTRAINT exercise_sets_set_number_check CHECK ((set_number > 0)),
    CONSTRAINT exercise_sets_warmup_check CHECK (((NOT is_warmup) OR ((reported_rir_bucket IS NULL) AND (rir_source IS NULL)))),
    CONSTRAINT exercise_sets_weight_check CHECK ((weight >= (0)::numeric))
);


--
-- Name: TABLE exercise_sets; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.exercise_sets IS 'Numbered workout set slots. In-progress sessions may contain blank slots until weight or reps are recorded.';


--
-- Name: COLUMN exercise_sets.rpe; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.exercise_sets.rpe IS 'Legacy/deprecated RPE observation retained for historical preservation; new app writes use reported RIR.';


--
-- Name: COLUMN exercise_sets.estimated_1rm_brzycki; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.exercise_sets.estimated_1rm_brzycki IS 'Brzycki estimate: weight * 36 / (37 - reps), rounded to 2 decimals; null outside 1-36 reps.';


--
-- Name: COLUMN exercise_sets.estimated_1rm_epley; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.exercise_sets.estimated_1rm_epley IS 'Epley estimate: weight * (1 + reps / 30), rounded to 2 decimals.';


--
-- Name: COLUMN exercise_sets.estimated_1rm_low; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.exercise_sets.estimated_1rm_low IS 'Lower of the unrounded Brzycki and Epley estimates, rounded to 2 decimals.';


--
-- Name: COLUMN exercise_sets.estimated_1rm_high; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.exercise_sets.estimated_1rm_high IS 'Higher of the unrounded Brzycki and Epley estimates, rounded to 2 decimals.';


--
-- Name: COLUMN exercise_sets.reported_rir_bucket; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.exercise_sets.reported_rir_bucket IS 'Entered reps-in-reserve bucket. Stored 4 means open-ended 4+ RIR; NULL applies only to warm-ups.';


--
-- Name: COLUMN exercise_sets.rir_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.exercise_sets.rir_source IS 'Provenance for reported RIR: user_entered or historical_backfill.';


--
-- Name: COLUMN exercise_sets.estimated_1rm_brzycki_rir_adjusted; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.exercise_sets.estimated_1rm_brzycki_rir_adjusted IS 'Brzycki estimate using completed reps plus reported RIR 0-3; NULL for warm-ups, 4+ RIR, or outside the 1-36 rep domain.';


--
-- Name: COLUMN exercise_sets.estimated_1rm_epley_rir_adjusted; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.exercise_sets.estimated_1rm_epley_rir_adjusted IS 'Epley estimate using completed reps plus reported RIR 0-3; NULL for warm-ups and 4+ RIR.';


