CREATE TABLE public.movement_mapping_versions (
    id bigint NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    status text NOT NULL,
    is_current boolean DEFAULT false NOT NULL,
    methodology_revision text NOT NULL,
    source_file_name text NOT NULL,
    source_sha256 text NOT NULL,
    payload_sha256 text NOT NULL,
    exercise_count integer NOT NULL,
    pattern_count integer NOT NULL,
    cell_count integer NOT NULL,
    nonzero_cell_count integer NOT NULL,
    change_notes text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    published_at timestamp with time zone,
    CONSTRAINT movement_mapping_versions_change_notes_check CHECK ((btrim(change_notes) <> ''::text)),
    CONSTRAINT movement_mapping_versions_check CHECK ((cell_count = (exercise_count * pattern_count))),
    CONSTRAINT movement_mapping_versions_check1 CHECK (((nonzero_cell_count >= 0) AND (nonzero_cell_count <= cell_count))),
    CONSTRAINT movement_mapping_versions_check2 CHECK (((NOT is_current) OR (status = 'published'::text))),
    CONSTRAINT movement_mapping_versions_check3 CHECK ((((status = 'draft'::text) AND (published_at IS NULL)) OR ((status = ANY (ARRAY['published'::text, 'retired'::text])) AND (published_at IS NOT NULL)))),
    CONSTRAINT movement_mapping_versions_code_check CHECK ((code ~ '^[a-z0-9_]+$'::text)),
    CONSTRAINT movement_mapping_versions_exercise_count_check CHECK ((exercise_count > 0)),
    CONSTRAINT movement_mapping_versions_methodology_revision_check CHECK ((btrim(methodology_revision) <> ''::text)),
    CONSTRAINT movement_mapping_versions_name_check CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT movement_mapping_versions_pattern_count_check CHECK ((pattern_count > 0)),
    CONSTRAINT movement_mapping_versions_payload_sha256_check CHECK ((payload_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT movement_mapping_versions_source_file_name_check CHECK ((btrim(source_file_name) <> ''::text)),
    CONSTRAINT movement_mapping_versions_source_sha256_check CHECK ((source_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT movement_mapping_versions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'retired'::text])))
);


